#!/usr/bin/env python3
"""
apply_phase5.py — Mission Control (Phase 5) one-shot apply

Run from your repo root:
    python3 apply_phase5.py

What it does:
  1. Backs up the existing html/war-rooms/bpo/bpo-internal1.html (if present)
     to the same path + ".bak"
  2. Writes the new bpo-internal1.html (all 6 sectors wired to
     TSMMissionStore/TSMMissionModel, docs/docsGenerated key collision fixed,
     4-column kanban + CSS fix, real intake -> real mission creation)
  3. Writes verify-mission-control.js to repo root (puppeteer browser check,
     with the pre-existing /core/* 404 noise filtered out of its error check)
  4. Sanity-checks the embedded JS (node --check) before writing anything,
     so a bad payload never touches your working tree
  5. Prints a diff --stat against the backup, same as your own apply scripts
"""

import base64
import subprocess
import sys
import os
import shutil

HTML_B64 = """

"""

JS_B64 = """

"""

HTML_DEST = "html/war-rooms/bpo/bpo-internal1.html"
JS_DEST = "verify-mission-control.js"


def decode(b64_str):
    return base64.b64decode("".join(b64_str.split()))


def check_js_syntax(js_bytes, label):
    tmp = "/tmp/_phase5_check.js"
    with open(tmp, "wb") as f:
        f.write(js_bytes)
    result = subprocess.run(["node", "--check", tmp], capture_output=True, text=True)
    os.remove(tmp)
    if result.returncode != 0:
        print(f"[FAIL] {label} failed node --check:")
        print(result.stderr)
        sys.exit(1)
    print(f"[OK]   {label} passed node --check")


def check_html_inline_script(html_bytes):
    import re
    html = html_bytes.decode("utf-8")
    scripts = re.findall(r"<script>(.*?)</script>", html, re.S)
    if not scripts:
        print("[FAIL] no inline <script> block found in HTML payload")
        sys.exit(1)
    check_js_syntax(scripts[0].encode("utf-8"), "bpo-internal1.html main inline script")


def main():
    html_bytes = decode(HTML_B64)
    js_bytes = decode(JS_B64)

    print(f"Decoded bpo-internal1.html: {len(html_bytes)} bytes")
    print(f"Decoded verify-mission-control.js: {len(js_bytes)} bytes")

    check_html_inline_script(html_bytes)
    check_js_syntax(js_bytes, "verify-mission-control.js")

    os.makedirs(os.path.dirname(HTML_DEST), exist_ok=True)

    if os.path.exists(HTML_DEST):
        backup = HTML_DEST + ".bak"
        shutil.copy2(HTML_DEST, backup)
        print(f"[OK]   backed up existing file -> {backup}")
    else:
        print(f"[OK]   no existing file at {HTML_DEST} (fresh write)")

    with open(HTML_DEST, "wb") as f:
        f.write(html_bytes)
    print(f"[OK]   wrote {HTML_DEST}")

    with open(JS_DEST, "wb") as f:
        f.write(js_bytes)
    print(f"[OK]   wrote {JS_DEST}")

    if os.path.exists(HTML_DEST + ".bak"):
        diff = subprocess.run(
            ["diff", "-u", HTML_DEST + ".bak", HTML_DEST],
            capture_output=True, text=True
        )
        added = sum(1 for l in diff.stdout.splitlines() if l.startswith("+") and not l.startswith("+++"))
        removed = sum(1 for l in diff.stdout.splitlines() if l.startswith("-") and not l.startswith("---"))
        print(f"[OK]   diff vs backup: +{added} -{removed} lines")

    print()
    print("All edits applied successfully.")
    print()
    print("Next steps:")
    print(f"  node --check {HTML_DEST}   # (won't work directly — it's HTML; use the check above)")
    print(f"  node {JS_DEST} {HTML_DEST}")
    print(f"  git diff --stat")
    print(f"  git add {HTML_DEST} {JS_DEST}")
    print(f'  git commit -m "Phase 5: Mission Control — wire bpo-internal1 to TSMMissionStore/Model"')


if __name__ == "__main__":
    main()